function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function go($p){header('Location: index.php?page='.$p);exit;}
function me(){return $_SESSION['u']??null;}
function need($roles=[]){if(!me())go('login');if($roles&&!in_array(me()['role'],$roles,true)){http_response_code(403);die('Access denied');}}
function flash($s){$_SESSION['f']=$s;}
function token(){if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(20));echo '<input type="hidden" name="csrf" value="'.e($_SESSION['csrf']).'">';}
function hist($db,$id,$status,$note=''){ $db->prepare('INSERT INTO issue_status_history(issue_id,status,note,updated_by) VALUES(?,?,?,?)')->execute([$id,$status,$note,me()['id']??null]);}
function rows($db,$where='1=1',$args=[]){$s=$db->prepare("SELECT i.*,c.name cat,d.name dept,u.name reporter FROM issues i JOIN categories c ON c.id=i.category_id JOIN users u ON u.id=i.user_id LEFT JOIN departments d ON d.id=i.department_id WHERE $where ORDER BY i.created_at DESC");$s->execute($args);return $s->fetchAll();}
function statusbadge($s){return '<span class="badge '.strtolower(str_replace(' ','-',$s)).'">'.e($s).'</span>';}
function tableissues($items,$admin=false){if(!$items){echo '<div class="empty">No issues found yet.</div>';return;}echo '<div class="scroll"><table><tr><th>Issue</th>'.($admin?'<th>Reporter</th>':'').'<th>Location</th><th>Priority</th><th>Status</th><th>Department</th><th></th></tr>';foreach($items as $i){echo '<tr><td><b>#'.str_pad($i['id'],5,'0',STR_PAD_LEFT).' '.e($i['title']).'</b><br><small>'.e($i['cat']).' · '.date('d M Y',strtotime($i['created_at'])).'</small></td>'.($admin?'<td>'.e($i['reporter']).'</td>':'').'<td>'.e($i['building']).'<br><small>'.e($i['floor'].' · '.$i['room']).'</small></td><td><span class="badge '.strtolower($i['priority']).'">'.e($i['priority']).'</span></td><td>'.statusbadge($i['status']).'</td><td>'.e($i['dept']??'Unassigned').'</td><td><a class="btn pale" href="index.php?page=detail&id='.$i['id'].'">View</a></td></tr>';}echo '</table></div>';}
