 ['Electrical Department','electrical','electrical@facilityfix.local'],
 ['Plumbing Department','plumbing','plumbing@facilityfix.local'],
 ['IT Support Department','it_support','itsupport@facilityfix.local'],
 ['Civil Maintenance Department','civil','civil@facilityfix.local'],
 ['Cleaning Department','cleaning','cleaning@facilityfix.local']
];
