if($_SERVER['REQUEST_METHOD']==='POST'){if(!isset($_POST['csrf'])||!hash_equals($_SESSION['csrf']??'',$_POST['csrf']))die('Invalid request. Reload page.');try{$act=$_POST['action']??'';
