elseif($login!==''){$s=$db->prepare('SELECT * FROM users WHERE username=? OR email=?');$s->execute([$login,$login]);}
elseif($email!==''){$s=$db->prepare('SELECT * FROM users WHERE email=?');$s->execute([$email]);}
