}
if($act==='register'){$name=trim($_POST['name']);$un=trim($_POST['username']);$email=trim($_POST['email']);$pw=$_POST['password'];$role=$_POST['role'];if(!$name||!$un||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pw)<4||$pw!==($_POST['confirm']??'')||!in_array($role,['student','teacher']))throw new Exception('Complete all fields. Passwords must match and contain at least 4 characters.');$s=$db->prepare('SELECT id FROM users WHERE username=? OR email=?');$s->execute([$un,$email]);if($s->fetch())throw new Exception('Username or email already exists.');$db->prepare('INSERT INTO users(name,username,email,phone,password,role) VALUES(?,?,?,?,?,?)')->execute([$name,$un,$email,trim($_POST['phone']??''),password_hash($pw,PASSWORD_DEFAULT),$role]);flash('Account created. Please sign in.');go('login');}
if($act==='report'){need(['student','teacher']);$required=['category_id','title','description','building','floor','room'];foreach($required as $k)if(trim($_POST[$k]??'')==='')throw new Exception('Please complete all required fields.');$photo=null;if(!empty($_FILES['photo']['name'])){if($_FILES['photo']['error']!==UPLOAD_ERR_OK||$_FILES['photo']['size']>3145728)throw new Exception('Photo upload failed or exceeds 3 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES['photo']['tmp_name']);$types=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($types[$mime]))throw new Exception('Use JPG, PNG or WEBP image.');$photo='uploads/'.bin2hex(random_bytes(12)).'.'.$types[$mime];if(!move_uploaded_file($_FILES['photo']['tmp_name'],__DIR__.'/'.$photo))throw new Exception('Could not save photo.');}$db->prepare("INSERT INTO issues(user_id,category_id,title,description,building,floor,room,photo) VALUES(?,?,?,?,?,?,?,?)")->execute([me()['id'],(int)$_POST['category_id'],trim($_POST['title']),trim($_POST['description']),trim($_POST['building']),trim($_POST['floor']),trim($_POST['room']),$photo]);$id=$db->lastInsertId();hist($db,$id,'Pending','Issue submitted');flash('Issue submitted. Issue ID: #'.str_pad($id,5,'0',STR_PAD_LEFT));go('my');}
