if($act==='update'){need(['department']);$id=(int)$_POST['id'];$st=$_POST['status'];if(!in_array($st,['Assigned','In Progress','Resolved']))throw new Exception('Invalid status.');$s=$db->prepare('UPDATE issues SET status=? WHERE id=? AND department_id=?');$s->execute([$st,$id,me()['department_id']]);if(!$s->rowCount())throw new Exception('This issue is not assigned to your department.');hist($db,$id,$st,trim($_POST['note']??''));flash('Status updated.');go('assigned');}
