<?php }elseif($page==='issues'){need(['admin']);?><div class="head"><div><div class="eyebrow">ADMINISTRATION</div><h1>Manage issues</h1><p class="muted">Set priority and assign a responsible department.</p></div></div><section class="panel"><?php $items=rows($db);if(!$items)echo '<div class="empty">No reports yet.</div>';else foreach($items as $i):?><div style="border-bottom:1px solid #edf1f6;padding:15px 0"><b>#<?=str_pad($i['id'],5,'0',STR_PAD_LEFT)?> · <?=e($i['title'])?></b><p class="muted"><?=e($i['reporter'])?> · <?=e($i['cat'])?> · <?=e($i['building'].' / '.$i['floor'].' / '.$i['room'])?> · <?=statusbadge($i['status'])?></p><form method="post" style="display:flex;gap:9px;flex-wrap:wrap;align-items:end"><?php token();?><input type="hidden" name="action" value="assign"><input type="hidden" name="id" value="<?=$i['id']?>"><div style="min-width:130px"><label>Priority</label><select name="priority"><?php foreach(['Low','Medium','High'] as $p):?><option <?=$i['priority']===$p?'selected':''?>><?=$p?></option><?php endforeach;?></select></div><div style="min-width:180px"><label>Department</label><select name="department_id"><option value="0">Unassigned</option><?php foreach($depts as $d):?><option value="<?=$d['id']?>" <?=(int)$i['department_id']===(int)$d['id']?'selected':''?>><?=e($d['name'])?></option><?php endforeach;?></select></div><button class="btn">Save assignment</button><a class="btn pale" href="index.php?page=detail&id=<?=$i['id']?>">Details & history</a></form></div><?php endforeach;?></section>
<?php }elseif($page==='assigned'){need(['department']);?><div class="head"><div><div class="eyebrow">DEPARTMENT WORKSPACE</div><h1>Assigned issues</h1><p class="muted">Update the status of work assigned to your department.</p></div></div><?php $items=rows($db,'i.department_id=?',[$u['department_id']]);if(!$items)echo '<div class="empty">No issues assigned yet.</div>';foreach($items as $i):?><section class="panel"><b>#<?=str_pad($i['id'],5,'0',STR_PAD_LEFT)?> · <?=e($i['title'])?></b><p class="muted"><?=e($i['cat'])?> · <?=e($i['building'].' / '.$i['floor'].' / '.$i['room'])?> · <?=statusbadge($i['status'])?></p><p><?=nl2br(e($i['description']))?></p><form method="post" style="display:flex;gap:9px;flex-wrap:wrap"><?php token();?><input type="hidden" name="action" value="update"><input type="hidden" name="id" value="<?=$i['id']?>"><select name="status" style="max-width:180px"><?php foreach(['Assigned','In Progress','Resolved'] as $st):?><option <?=$i['status']===$st?'selected':''?>><?=$st?></option><?php endforeach;?></select><input name="note" placeholder="Work note (optional)" style="max-width:300px"><button class="btn">Update status</button><a class="btn pale" href="index.php?page=detail&id=<?=$i['id']?>">History</a></form></section><?php endforeach;?>
<?php }elseif($page==='detail'){need();$id=(int)($_GET['id']??0);$list=rows($db,'i.id=?',[$id]);$i=$list[0]??null;if(!$i||($role!=='admin'&&!($role==='department'&&(int)$i['department_id']===(int)$u['department_id'])&&(int)$i['user_id']!==(int)$u['id']))echo '<div class="alert error">Issue not found or access denied.</div>';else{$s=$db->prepare('SELECT h.*,u.name updater FROM issue_status_history h LEFT JOIN users u ON u.id=h.updated_by WHERE issue_id=? ORDER BY h.created_at DESC');$s->execute([$id]);?><div class="head"><div><div class="eyebrow">ISSUE DETAILS</div><h1>#<?=str_pad($i['id'],5,'0',STR_PAD_LEFT)?> · <?=e($i['title'])?></h1><p class="muted">Submitted <?=date('d M Y, h:i A',strtotime($i['created_at']))?></p></div></div><div class="cols"><section class="panel"><h3>Issue information</h3><p><b>Description</b><br><?=nl2br(e($i['description']))?></p><p><b>Category:</b> <?=e($i['cat'])?></p><p><b>Location:</b> <?=e($i['building'].' · '.$i['floor'].' · '.$i['room'])?></p><p><b>Priority:</b> <?=e($i['priority'])?> &nbsp; <b>Status:</b> <?=statusbadge($i['status'])?></p><p><b>Department:</b> <?=e($i['dept']??'Unassigned')?></p><?php if($i['photo']):?><img src="<?=e($i['photo'])?>" style="max-width:100%;max-height:300px;border-radius:12px"><?php endif;?></section><?php if(in_array($role,['student','teacher'],true)&&(int)$i['user_id']===(int)$u['id']&&$i['status']==='Resolved'){$rv=$db->prepare('SELECT * FROM reviews WHERE issue_id=?');$rv->execute([$id]);$existingReview=$rv->fetch();if(!$existingReview):?><section class="panel review-panel"><h3>Review this resolved issue</h3><p class="muted">Rate the handling of this issue from 1 to 5 stars.</p><form method="post"><?php token();?><input type="hidden" name="action" value="review"><input type="hidden" name="issue_id" value="<?=$id?>"><div class="field"><label>Rating</label><select name="rating" required><option value="">Choose rating</option><option value="5">5 - Excellent</option><option value="4">4 - Good</option><option value="3">3 - Average</option><option value="2">2 - Poor</option><option value="1">1 - Very poor</option></select></div><div class="field"><label>Comment (optional)</label><textarea name="comment" maxlength="1000" placeholder="Share your feedback"></textarea></div><button class="btn">Submit review</button></form></section><?php else:?><section class="panel"><h3>Your review</h3><p><b>Rating:</b> <?=str_repeat('★',(int)$existingReview['rating'])?><?=str_repeat('☆',5-(int)$existingReview['rating'])?></p><p><?=e($existingReview['comment']?:'No comment added.')?></p></section><?php endif;}?>
<section class="panel"><h3>Status history</h3><?php foreach($s as $h):?><p style="border-left:3px solid #bcd8f7;padding-left:12px"><b><?=e($h['status'])?></b><br><small><?=date('d M Y h:i A',strtotime($h['created_at']))?> · <?=e($h['updater']??'System')?></small><br><?=e($h['note'])?></p><?php endforeach;?></section></div><?php }?>
<?php }elseif($page==='users'){need(['admin']);?><div class="head"><div><div class="eyebrow">ADMINISTRATION</div><h1>Manage users</h1><p class="muted">Registered users and department accounts.</p></div></div><section class="panel"><div class="scroll"><table><tr><th>Name</th><th>Username</th><th>Email</th><th>Role</th><th>Department</th></tr><?php foreach($db->query('SELECT u.*,d.name dept FROM users u LEFT JOIN departments d ON d.id=u.department_id ORDER BY u.id DESC') as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['username'])?></td><td><?=e($r['email'])?></td><td><?=e($r['role'])?></td><td><?=e($r['dept']??'—')?></td></tr><?php endforeach;?></table></div></section>
<?php }elseif($page==='departments'){need(['admin']);?><div class="head"><div><div class="eyebrow">ADMINISTRATION</div><h1>Departments</h1><p class="muted">Teams available for assignment.</p></div></div><div class="quick"><?php foreach($depts as $d):$s=$db->prepare('SELECT COUNT(*) FROM issues WHERE department_id=?');$s->execute([$d['id']]);?><div class="qcard"><span class="icon">⚙</span><h3><?=e($d['name'])?></h3><p><?=e($d['description'])?></p><b><?=$s->fetchColumn()?></b> assigned issues</div><?php endforeach;?></div>
<?php }elseif($page==='reports'){need(['admin']);$total=(int)$db->query('SELECT COUNT(*) FROM issues')->fetchColumn();?><div class="head"><div><div class="eyebrow">INSIGHTS</div><h1>Reports & analytics</h1><p class="muted">Summaries calculated from saved issue records.</p></div><button class="btn pale" onclick="window.print()">Print report</button></div><div class="stats"><?php foreach(['Total issues'=>'SELECT COUNT(*) FROM issues','Pending'=>'SELECT COUNT(*) FROM issues WHERE status="Pending"','In progress'=>'SELECT COUNT(*) FROM issues WHERE status="In Progress"','Resolved'=>'SELECT COUNT(*) FROM issues WHERE status="Resolved"'] as $lab=>$query):?><div class="stat"><div><small><?=$lab?></small><strong><?=$db->query($query)->fetchColumn()?></strong></div><span class="icon">▥</span></div><?php endforeach;?></div><div class="cols"><section class="panel"><h3>Issues by category</h3><?php $rs=$db->query('SELECT c.name,COUNT(i.id) n FROM categories c LEFT JOIN issues i ON c.id=i.category_id GROUP BY c.id ORDER BY n DESC')->fetchAll();$mx=max(1,max(array_column($rs,'n')?:[1]));foreach($rs as $r):?><p><?=e($r['name'])?><b style="float:right"><?=$r['n']?></b></p><div style="height:8px;background:#edf2f7;border-radius:8px;margin-bottom:15px"><div style="height:8px;background:#267fd0;border-radius:8px;width:<?=round($r['n']/$mx*100)?>%"></div></div><?php endforeach;?></section><section class="panel"><h3>Issues by department</h3><?php $rs=$db->query('SELECT d.name,COUNT(i.id) n FROM departments d LEFT JOIN issues i ON d.id=i.department_id GROUP BY d.id ORDER BY n DESC')->fetchAll();$mx=max(1,max(array_column($rs,'n')?:[1]));foreach($rs as $r):?><p><?=e($r['name'])?><b style="float:right"><?=$r['n']?></b></p><div style="height:8px;background:#edf2f7;border-radius:8px;margin-bottom:15px"><div style="height:8px;background:#267fd0;border-radius:8px;width:<?=round($r['n']/$mx*100)?>%"></div></div><?php endforeach;?></section></div>
<?php }elseif($page==='reviews'){need();?><div class="head"><div><div class="eyebrow">FEEDBACK</div><h1><?= $role==='admin'?'Issue reviews':'My reviews' ?></h1><p class="muted"><?= $role==='admin'?'Review ratings and comments submitted by users.':'Review your feedback for resolved issues.' ?></p></div></div><section class="panel"><div class="scroll"><table><tr><th>Issue</th><?php if($role==='admin'):?><th>Reviewer</th><?php endif;?><th>Rating</th><th>Comment</th><th>Date</th></tr><?php if($role==='admin'){$reviewRows=$db->query('SELECT r.*,i.title,u.name reviewer FROM reviews r JOIN issues i ON i.id=r.issue_id JOIN users u ON u.id=r.user_id ORDER BY r.created_at DESC')->fetchAll();}else{$q=$db->prepare('SELECT r.*,i.title,u.name reviewer FROM reviews r JOIN issues i ON i.id=r.issue_id JOIN users u ON u.id=r.user_id WHERE r.user_id=? ORDER BY r.created_at DESC');$q->execute([$u['id']]);$reviewRows=$q->fetchAll();}if(!$reviewRows):?><tr><td colspan="5">No reviews have been submitted yet.</td></tr><?php else:foreach($reviewRows as $rr):?><tr><td><a href="index.php?page=detail&id=<?=$rr['issue_id']?>">#<?=str_pad($rr['issue_id'],5,'0',STR_PAD_LEFT)?> · <?=e($rr['title'])?></a></td><?php if($role==='admin'):?><td><?=e($rr['reviewer'])?></td><?php endif;?><td><span class="rating-stars"><?=str_repeat('★',(int)$rr['rating'])?><?=str_repeat('☆',5-(int)$rr['rating'])?></span> (<?=$rr['rating']?>/5)</td><td><?=e($rr['comment']?:'—')?></td><td><?=date('d M Y',strtotime($rr['created_at']))?></td></tr><?php endforeach;endif;?></table></div></section>
<?php }elseif($page==='profile'){need();$s=$db->prepare('SELECT * FROM users WHERE id=?');$s->execute([$u['id']]);$prof=$s->fetch();?><div class="head"><div><div class="eyebrow">ACCOUNT</div><h1>My profile</h1><p class="muted">Update your account details.</p></div></div><section class="formcard" style="max-width:650px"><form method="post"><?php token();?><input type="hidden" name="action" value="profile"><div class="field"><label>Name</label><input name="name" value="<?=e($prof['name'])?>" required></div><div class="field"><label>Username</label><input value="<?=e($prof['username'])?>" disabled></div><div class="field"><label>Email</label><input type="email" name="email" value="<?=e($prof['email'])?>" required></div><div class="field"><label>Phone</label><input name="phone" value="<?=e($prof['phone'])?>"></div><button class="btn">Save profile</button></form></section>
<?php }else{?><div class="head"><h1>Page not found</h1></div><?php }?>
